const DESKTOP_EXE_B64 = "";
const DESKTOP_BAT_TPL = "/* 2>nul\n@echo off\nchcp 65001 >nul\ntitle HEXTECH 推荐官 · 桌面透明悬浮窗启动器\necho ================================================================\necho   HEXTECH 推荐官 · 正在初始化 Windows 桌面透明悬浮窗 (.exe) ...\necho ================================================================\n\nset \"INSTALL_DIR=%LOCALAPPDATA%\\HextechOverlay\"\nif not exist \"%INSTALL_DIR%\" mkdir \"%INSTALL_DIR%\"\nset \"EXE_FILE=%INSTALL_DIR%\\HEXTECH透明悬浮窗.exe\"\nset \"LOCAL_EXE=%~dp0HEXTECH透明悬浮窗.exe\"\n\nset \"CSC=\"\nif exist \"%WINDIR%\\Microsoft.NET\\Framework64\\v4.0.30319\\csc.exe\" (\n    set \"CSC=%WINDIR%\\Microsoft.NET\\Framework64\\v4.0.30319\\csc.exe\"\n) else if exist \"%WINDIR%\\Microsoft.NET\\Framework\\v4.0.30319\\csc.exe\" (\n    set \"CSC=%WINDIR%\\Microsoft.NET\\Framework\\v4.0.30319\\csc.exe\"\n)\n\nif \"%CSC%\"==\"\" (\n    echo [错误] 未检测到系统内置 .NET Framework 4.0 编译器。\n    pause\n    exit /b 1\n)\n\ntaskkill /F /IM \"HEXTECH透明悬浮窗.exe\" >nul 2>&1\n\n\"%CSC%\" /nologo /target:winexe /out:\"%EXE_FILE%\" /optimize+ \"%~f0\"\nif %ERRORLEVEL% NEQ 0 (\n    echo [提示] 正在重试编译...\n    pause\n    exit /b 1\n)\n\ncopy /Y \"%EXE_FILE%\" \"%LOCAL_EXE%\" >nul 2>&1\n\n:: 自动在桌面创建快捷方式\npowershell -NoProfile -ExecutionPolicy Bypass -Command \"$s=(New-Object -COM WScript.Shell).CreateShortcut([Environment]::GetFolderPath('Desktop')+'\\HEXTECH透明悬浮窗.lnk');$s.TargetPath='%EXE_FILE%';$s.Description='HEXTECH 海克斯大乱斗透明置顶悬浮窗';$s.Save()\" >nul 2>&1\n\necho [成功] 已生成 HEXTECH透明悬浮窗.exe 并在桌面创建快捷方式！\necho 正在启动透明悬浮窗...\nstart \"\" \"%EXE_FILE%\"\nexit /b 0\n*/\nusing System;\nusing System.Diagnostics;\nusing System.Drawing;\nusing System.IO;\nusing System.Runtime.InteropServices;\nusing System.Text;\nusing System.Windows.Forms;\n\nnamespace HextechOverlay\n{\n    public class ControlBarForm : Form\n    {\n        [DllImport(\"user32.dll\")] static extern bool SetWindowPos(IntPtr hWnd, IntPtr hWndInsertAfter, int X, int Y, int cx, int cy, uint uFlags);\n        [DllImport(\"user32.dll\")] static extern int GetWindowLong(IntPtr hWnd, int nIndex);\n        [DllImport(\"user32.dll\")] static extern int SetWindowLong(IntPtr hWnd, int nIndex, int dwNewLong);\n        [DllImport(\"user32.dll\")] static extern bool SetLayeredWindowAttributes(IntPtr hwnd, uint crKey, byte bAlpha, uint dwFlags);\n        [DllImport(\"user32.dll\")] static extern bool SetWindowDisplayAffinity(IntPtr hWnd, uint dwAffinity);\n        [DllImport(\"user32.dll\")] static extern int SetWindowRgn(IntPtr hWnd, IntPtr hRgn, bool bRedraw);\n        [DllImport(\"gdi32.dll\")] static extern IntPtr CreateRoundRectRgn(int x1, int y1, int x2, int y2, int cx, int cy);\n        [DllImport(\"user32.dll\")] static extern bool RegisterHotKey(IntPtr hWnd, int id, uint fsModifiers, uint vk);\n        [DllImport(\"user32.dll\")] static extern bool UnregisterHotKey(IntPtr hWnd, int id);\n        [DllImport(\"user32.dll\")] static extern bool EnumWindows(EnumWindowsProc enumProc, IntPtr lParam);\n        [DllImport(\"user32.dll\")] static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);\n        [DllImport(\"user32.dll\")] static extern bool IsWindowVisible(IntPtr hWnd);\n        [DllImport(\"user32.dll\")] static extern bool PostMessage(IntPtr hWnd, uint Msg, IntPtr wParam, IntPtr lParam);\n\n        delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);\n\n        static readonly IntPtr HWND_TOPMOST = new IntPtr(-1);\n        const uint SWP_SHOWWINDOW = 0x0040;\n        const uint SWP_NOACTIVATE = 0x0010;\n        const int GWL_EXSTYLE = -20;\n        const int WS_EX_LAYERED = 0x00080000;\n        const int WS_EX_TRANSPARENT = 0x00000020;\n        const int WS_EX_TOPMOST = 0x00000008;\n        const int WS_EX_TOOLWINDOW = 0x00000080;\n        const uint LWA_ALPHA = 0x00000002;\n        const uint WDA_EXCLUDEFROMCAPTURE = 0x00000011;\n        const uint MOD_ALT = 0x0001;\n        const int HOTKEY_CLICKTHROUGH = 9001; // Alt + X\n        const int HOTKEY_TOGGLE_SIZE  = 9002; // Alt + Z\n        const int TITLE_CROP = 32; // 裁剪掉浏览器默认标题栏高度\n\n        private NotifyIcon tray;\n        private Timer monitorTimer;\n        private IntPtr targetHwnd = IntPtr.Zero;\n        private bool isClickThrough = false;\n        private bool isFolded = false; // 默认展开完整面板方便新手操作，按 Alt+Z 可随时收起为胶囊\n        private byte currentAlpha = 232; // 默认 ~91% 透明度\n        private int winX = 0, winY = 12;\n        private bool dragging = false;\n        private Point dragStart;\n\n        private Label lblDrag;\n        private Button btnPass;\n        private Button btnFold;\n        private Button btnAlpha;\n        private Button btnClose;\n\n        private string appUrl = \"__APP_ORIGIN__/?desktop=1\";\n\n        public ControlBarForm()\n        {\n            var wa = Screen.PrimaryScreen.WorkingArea;\n            int initW = 352;\n            winX = wa.Right - initW - 14;\n            winY = wa.Top + 14;\n\n            this.Text = \"HEXTECH 控制栏\";\n            this.FormBorderStyle = FormBorderStyle.None;\n            this.ShowInTaskbar = false;\n            this.TopMost = true;\n            this.StartPosition = FormStartPosition.Manual;\n            this.Bounds = new Rectangle(winX, winY, initW, 28);\n            this.BackColor = Color.FromArgb(11, 22, 38);\n\n            lblDrag = new Label()\n            {\n                Text = \" ⚔ HEXTECH 悬浮窗 (按住拖动)\",\n                ForeColor = Color.FromArgb(240, 195, 90),\n                Font = new Font(\"Microsoft YaHei UI\", 8.5f, FontStyle.Bold),\n                AutoSize = false,\n                Bounds = new Rectangle(2, 2, 148, 24),\n                TextAlign = ContentAlignment.MiddleLeft,\n                Cursor = Cursors.SizeAll\n            };\n            lblDrag.MouseDown += OnDragDown;\n            lblDrag.MouseMove += OnDragMove;\n            lblDrag.MouseUp += OnDragUp;\n\n            btnPass = MakeBtn(\"穿透:关(Alt+X)\", 152, 78, Color.FromArgb(25, 211, 230));\n            btnPass.Click += (s, e) => ToggleClickThrough();\n\n            btnFold = MakeBtn(\"折叠(Alt+Z)\", 232, 62, Color.FromArgb(230, 241, 247));\n            btnFold.Click += (s, e) => ToggleSize();\n\n            btnAlpha = MakeBtn(\"90%\", 296, 30, Color.FromArgb(140, 170, 190));\n            btnAlpha.Click += (s, e) => CycleOpacity();\n\n            btnClose = MakeBtn(\"✕\", 328, 22, Color.FromArgb(255, 107, 122));\n            btnClose.Click += (s, e) => ExitApp();\n\n            this.Controls.AddRange(new Control[] { lblDrag, btnPass, btnFold, btnAlpha, btnClose });\n\n            var menu = new ContextMenuStrip();\n            menu.Items.Add(\"展开 / 折叠胶囊面板 (Alt+Z)\", null, (s, e) => ToggleSize());\n            menu.Items.Add(\"开启 / 关闭鼠标穿透 (Alt+X)\", null, (s, e) => ToggleClickThrough());\n            menu.Items.Add(\"切换透明度 (90% / 75% / 100%)\", null, (s, e) => CycleOpacity());\n            menu.Items.Add(\"重置到屏幕右上角\", null, (s, e) => { winX = Screen.PrimaryScreen.WorkingArea.Right - (isFolded ? 256 : 352) - 14; winY = 14; SyncOverlayPosition(); });\n            menu.Items.Add(new ToolStripSeparator());\n            menu.Items.Add(\"退出 HEXTECH 悬浮窗\", null, (s, e) => ExitApp());\n\n            tray = new NotifyIcon()\n            {\n                Icon = SystemIcons.Shield,\n                Text = \"HEXTECH 透明悬浮窗 (Alt+X 鼠标穿透 | Alt+Z 折叠)\",\n                ContextMenuStrip = menu,\n                Visible = true\n            };\n            tray.DoubleClick += (s, e) => ToggleSize();\n\n            LaunchOverlayBrowser();\n\n            monitorTimer = new Timer();\n            monitorTimer.Interval = 400;\n            monitorTimer.Tick += MonitorLoop;\n            monitorTimer.Start();\n        }\n\n        private Button MakeBtn(string txt, int x, int w, Color fg)\n        {\n            var b = new Button()\n            {\n                Text = txt,\n                Bounds = new Rectangle(x, 3, w, 22),\n                FlatStyle = FlatStyle.Flat,\n                BackColor = Color.FromArgb(16, 34, 56),\n                ForeColor = fg,\n                Font = new Font(\"Microsoft YaHei UI\", 7.5f, FontStyle.Bold),\n                Cursor = Cursors.Hand,\n                TabStop = false\n            };\n            b.FlatAppearance.BorderSize = 1;\n            b.FlatAppearance.BorderColor = Color.FromArgb(35, 75, 105);\n            return b;\n        }\n\n        protected override void OnHandleCreated(EventArgs e)\n        {\n            base.OnHandleCreated(e);\n            int ex = GetWindowLong(this.Handle, GWL_EXSTYLE);\n            SetWindowLong(this.Handle, GWL_EXSTYLE, ex | WS_EX_TOPMOST | WS_EX_TOOLWINDOW);\n            try { SetWindowDisplayAffinity(this.Handle, WDA_EXCLUDEFROMCAPTURE); } catch { }\n            RegisterHotKey(this.Handle, HOTKEY_CLICKTHROUGH, MOD_ALT, (uint)Keys.X);\n            RegisterHotKey(this.Handle, HOTKEY_TOGGLE_SIZE, MOD_ALT, (uint)Keys.Z);\n        }\n\n        protected override void OnPaint(PaintEventArgs e)\n        {\n            base.OnPaint(e);\n            using (var p = new Pen(Color.FromArgb(240, 195, 90), 1))\n            {\n                e.Graphics.DrawRectangle(p, 0, 0, this.Width - 1, this.Height - 1);\n            }\n        }\n\n        private void OnDragDown(object sender, MouseEventArgs e)\n        {\n            if (e.Button == MouseButtons.Left) { dragging = true; dragStart = e.Location; }\n        }\n        private void OnDragMove(object sender, MouseEventArgs e)\n        {\n            if (!dragging) return;\n            winX += e.X - dragStart.X;\n            winY += e.Y - dragStart.Y;\n            SyncOverlayPosition();\n        }\n        private void OnDragUp(object sender, MouseEventArgs e) { dragging = false; }\n\n        private void LaunchOverlayBrowser()\n        {\n            string[] candidates = new string[]\n            {\n                @\"C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe\",\n                @\"C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe\",\n                @\"C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe\",\n                @\"C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe\"\n            };\n            string browserExe = \"msedge.exe\";\n            foreach (var p in candidates) { if (File.Exists(p)) { browserExe = p; break; } }\n\n            string userDataDir = Path.Combine(Path.GetTempPath(), \"HextechOverlayApp_v2\");\n            string args = string.Format(\n                \"--app=\\\"{0}\\\" --user-data-dir=\\\"{1}\\\" --window-size=352,540 --window-position={2},{3} --auto-select-desktop-capture-source=\\\"Entire screen\\\"\",\n                appUrl, userDataDir, winX, winY\n            );\n            try { Process.Start(browserExe, args); } catch { }\n        }\n\n        private void MonitorLoop(object sender, EventArgs e)\n        {\n            if (targetHwnd == IntPtr.Zero || !IsWindowVisible(targetHwnd))\n            {\n                targetHwnd = FindOverlayWindow();\n                if (targetHwnd != IntPtr.Zero)\n                {\n                    ApplyStyles();\n                    SyncOverlayPosition();\n                }\n            }\n            else\n            {\n                SetWindowPos(targetHwnd, HWND_TOPMOST, 0, 0, 0, 0, 0x0002 | 0x0001 | SWP_NOACTIVATE);\n                SetWindowPos(this.Handle, HWND_TOPMOST, 0, 0, 0, 0, 0x0002 | 0x0001 | SWP_NOACTIVATE);\n            }\n        }\n\n        private IntPtr FindOverlayWindow()\n        {\n            IntPtr found = IntPtr.Zero;\n            EnumWindows((hWnd, lParam) =>\n            {\n                if (!IsWindowVisible(hWnd) || hWnd == this.Handle) return true;\n                StringBuilder sb = new StringBuilder(256);\n                GetWindowText(hWnd, sb, 256);\n                string t = sb.ToString();\n                if (t.Contains(\"海克斯大乱斗\") || t.Contains(\"HEXTECH Recommended\") || t.Contains(\"hks.mongovanee\"))\n                {\n                    found = hWnd;\n                    return false;\n                }\n                return true;\n            }, IntPtr.Zero);\n            return found;\n        }\n\n        private void ApplyStyles()\n        {\n            if (targetHwnd == IntPtr.Zero) return;\n            int ex = GetWindowLong(targetHwnd, GWL_EXSTYLE);\n            ex |= WS_EX_LAYERED | WS_EX_TOPMOST;\n            if (isClickThrough) ex |= WS_EX_TRANSPARENT;\n            else ex &= ~WS_EX_TRANSPARENT;\n            SetWindowLong(targetHwnd, GWL_EXSTYLE, ex);\n            SetLayeredWindowAttributes(targetHwnd, 0, currentAlpha, LWA_ALPHA);\n            try { SetWindowDisplayAffinity(targetHwnd, WDA_EXCLUDEFROMCAPTURE); } catch { }\n        }\n\n        private void SyncOverlayPosition()\n        {\n            int w = isFolded ? 256 : 352;\n            int webH = isFolded ? 98 : 548;\n            this.Bounds = new Rectangle(winX, winY, w, 28);\n            if (isFolded)\n            {\n                lblDrag.Width = 76;\n                lblDrag.Text = \" ⚔ 拖动\";\n                btnPass.Bounds = new Rectangle(78, 3, 82, 22);\n                btnFold.Bounds = new Rectangle(162, 3, 66, 22);\n                btnAlpha.Visible = false;\n                btnClose.Bounds = new Rectangle(230, 3, 22, 22);\n            }\n            else\n            {\n                lblDrag.Width = 148;\n                lblDrag.Text = \" ⚔ HEXTECH 悬浮窗 (按住拖动)\";\n                btnPass.Bounds = new Rectangle(152, 3, 78, 22);\n                btnFold.Bounds = new Rectangle(232, 3, 62, 22);\n                btnAlpha.Visible = true;\n                btnAlpha.Bounds = new Rectangle(296, 3, 30, 22);\n                btnClose.Bounds = new Rectangle(328, 3, 22, 22);\n            }\n            this.Invalidate();\n\n            if (targetHwnd != IntPtr.Zero)\n            {\n                // 将网页窗口置于控制栏正下方，并用 SetWindowRgn 裁掉浏览器顶部 32px 默认白边标题栏\n                SetWindowPos(targetHwnd, HWND_TOPMOST, winX, winY + 28 - TITLE_CROP, w, webH, SWP_SHOWWINDOW | SWP_NOACTIVATE);\n                IntPtr rgn = CreateRoundRectRgn(0, TITLE_CROP, w + 1, webH + 1, 10, 10);\n                SetWindowRgn(targetHwnd, rgn, true);\n            }\n        }\n\n        private void ToggleSize()\n        {\n            int oldW = isFolded ? 256 : 352;\n            isFolded = !isFolded;\n            int newW = isFolded ? 256 : 352;\n            winX = Math.Max(0, winX + oldW - newW); // 保持右边缘对齐\n            btnFold.Text = isFolded ? \"展开(Alt+Z)\" : \"折叠(Alt+Z)\";\n            SyncOverlayPosition();\n        }\n\n        private void ToggleClickThrough()\n        {\n            isClickThrough = !isClickThrough;\n            btnPass.Text = isClickThrough ? \"🔥穿透中(Alt+X)\" : \"穿透:关(Alt+X)\";\n            btnPass.BackColor = isClickThrough ? Color.FromArgb(60, 42, 12) : Color.FromArgb(16, 34, 56);\n            btnPass.ForeColor = isClickThrough ? Color.FromArgb(240, 195, 90) : Color.FromArgb(25, 211, 230);\n            ApplyStyles();\n        }\n\n        private void CycleOpacity()\n        {\n            if (currentAlpha == 232) { currentAlpha = 188; btnAlpha.Text = \"75%\"; }\n            else if (currentAlpha == 188) { currentAlpha = 255; btnAlpha.Text = \"100%\"; }\n            else { currentAlpha = 232; btnAlpha.Text = \"90%\"; }\n            ApplyStyles();\n        }\n\n        protected override void WndProc(ref Message m)\n        {\n            if (m.Msg == 0x0312)\n            {\n                int id = m.WParam.ToInt32();\n                if (id == HOTKEY_CLICKTHROUGH) ToggleClickThrough();\n                else if (id == HOTKEY_TOGGLE_SIZE) ToggleSize();\n            }\n            base.WndProc(ref m);\n        }\n\n        private void ExitApp()\n        {\n            UnregisterHotKey(this.Handle, HOTKEY_CLICKTHROUGH);\n            UnregisterHotKey(this.Handle, HOTKEY_TOGGLE_SIZE);\n            if (targetHwnd != IntPtr.Zero) PostMessage(targetHwnd, 0x0010, IntPtr.Zero, IntPtr.Zero); // WM_CLOSE\n            tray.Visible = false;\n            Application.Exit();\n        }\n\n        [STAThread]\n        static void Main()\n        {\n            Application.EnableVisualStyles();\n            Application.SetCompatibleTextRenderingDefault(false);\n            Application.Run(new ControlBarForm());\n        }\n    }\n}\n";
